import SwiftUI

// MARK: - Language

enum AppLanguage: String, CaseIterable {
    case german   = "de"
    case english  = "en"
    case italian  = "it"
    case french   = "fr"
    case spanish  = "es"

    var label: String {
        switch self {
        case .german:  return "Deutsch"
        case .english: return "English"
        case .italian: return "Italiano"
        case .french:  return "Français"
        case .spanish: return "Español"
        }
    }
    /// Kurzes 2-Buchstaben-Kürzel für das Toggle in der Toolbar.
    var shortCode: String {
        switch self {
        case .german:  return "DE"
        case .english: return "EN"
        case .italian: return "IT"
        case .french:  return "FR"
        case .spanish: return "ES"
        }
    }
    /// Flagge für den Picker, damit die Sprache ohne Lesen erkannt wird.
    var flag: String {
        switch self {
        case .german:  return "🇩🇪"
        case .english: return "🇬🇧"
        case .italian: return "🇮🇹"
        case .french:  return "🇫🇷"
        case .spanish: return "🇪🇸"
        }
    }
}

