    "push.reengage.1_body":     ["de": "…läuft 200m weg jemand mit Kaffee an dir vorbei. Komm dazu.", "en": "…someone with coffee walks past you 200m away. Join in.", "it": "…qualcuno con il caffè ti passa accanto a 200m. Unisciti.", "fr": "…quelqu'un avec un café passe à 200m. Rejoins.", "es": "…alguien con café pasa a 200m. Únete."],
