    "push.reengage.2_body":     ["de": "Hier antwortet keiner mit \"bald\". Starte eine Runde — wer Bock hat kommt dazu.", "en": "Nobody here replies \"soon\". Start a round — whoever's in joins.", "it": "Qui nessuno risponde \"presto\". Avvia una sessione — chi vuole si unisce.", "fr": "Personne ne répond \"bientôt\" ici. Lance une session — ceux qui veulent rejoignent.", "es": "Aquí nadie dice \"pronto\". Lanza una sesión — se une quien quiera."],
    "push.reengage.3_title":    ["de": "Geht in 60 Sekunden raus", "en": "Out in 60 seconds", "it": "Fuori in 60 secondi", "fr": "Dehors en 60 secondes", "es": "Fuera en 60 segundos"],
    "push.reengage.3_body":     ["de": "Runde starten, jemand kommt dazu, fertig. Echt so einfach.", "en": "Start a round, someone joins, done. That simple.", "it": "Avvia la sessione, qualcuno si unisce, fatto. Così semplice.", "fr": "Lance une session, quelqu'un rejoint, c'est fait. Aussi simple.", "es": "Lanza sesión, alguien se une, listo. Así de simple."],
    "push.reengage.4_title":    ["de": "Deine Stadt schläft nicht", "en": "Your city doesn't sleep", "it": "La tua città non dorme", "fr": "Ta ville ne dort pas", "es": "Tu ciudad no duerme"],
    "push.reengage.4_body":     ["de": "Bier, Park, Spaziergang. Starte eine Runde — sofort sichtbar.", "en": "Beer, park, walk. Start a round — instantly live.", "it": "Birra, parco, passeggiata. Avvia una sessione — subito live.", "fr": "Bière, parc, balade. Lance une session — direct en ligne.", "es": "Cerveza, parque, paseo. Lanza una sesión — al instante en vivo."],
    "push.reengage.5_title":    ["de": "Spontan oder nie", "en": "Spontaneous or never", "it": "Spontaneo o mai", "fr": "Spontané ou jamais", "es": "Espontáneo o nunca"],
    "push.reengage.5_body":     ["de": "Heute Abend? In 10 Min kannst du draußen sein. Probier's.", "en": "Tonight? You can be outside in 10 min. Try it.", "it": "Stasera? In 10 min sei fuori. Prova.", "fr": "Ce soir ? Tu peux être dehors en 10 min. Essaie.", "es": "¿Esta noche? En 10 min estás fuera. Pruébalo."],
    "push.reengage.6_title":    ["de": "Chat oder Treffen?", "en": "Chat or meet?", "it": "Chat o incontro?", "fr": "Chat ou rencontre ?", "es": "¿Chat o quedada?"],
    "push.reengage.6_body":     ["de": "dazu überspringt den Chat. Starten, hin, fertig.", "en": "dazu skips the chat. Start, go, done.", "it": "dazu salta la chat. Avvia, vai, fatto.", "fr": "dazu saute le chat. Lance, vas-y, c'est fait.", "es": "dazu se salta el chat. Lanza, ve, listo."],
    "push.reengage.7_title":    ["de": "Jeder hier hat grad Bock", "en": "Everyone here's down right now", "it": "Tutti qui hanno voglia", "fr": "Tout le monde est partant ici", "es": "Aquí todos tienen ganas"],
    "push.reengage.7_body":     ["de": "Ein Tap und du siehst wer in deiner Stadt jetzt was startet.", "en": "One tap and you see who's starting something in your city.", "it": "Un tap e vedi chi lancia qualcosa nella tua città.", "fr": "Un tap et tu vois qui lance quelque chose dans ta ville.", "es": "Un toque y ves quién lanza algo en tu ciudad."],
    "push.reengage.8_title":    ["de": "Spontan ist das neue Geplant", "en": "Spontaneous is the new planned", "it": "Spontaneo è il nuovo pianificato", "fr": "Spontané c'est le nouveau planifié", "es": "Espontáneo es lo nuevo planificado"],
    "push.reengage.8_body":     ["de": "Während andere planen, kommst du dazu. Karte auf, hingehen, fertig.", "en": "While others plan, you show up. Map open, go, done.", "it": "Mentre altri pianificano, tu ti presenti. Mappa aperta, vai, fatto.", "fr": "Pendant que les autres planifient, tu te pointes. Carte ouverte, vas-y, c'est fait.", "es": "Mientras otros planean, tú apareces. Mapa abierto, ve, listo."],
    "push.reengage.9_title":    ["de": "Spontan ist das neue Geplant", "en": "Spontaneous is the new planned", "it": "Spontaneo è il nuovo pianificato", "fr": "Spontané c'est le nouveau planifié", "es": "Espontáneo es lo nuevo planificado"],
    "push.reengage.9_body":     ["de": "Wer wartet bis Donnerstag, verpasst Sonntag. Komm einfach dazu.", "en": "Wait until Thursday and you'll miss Sunday. Just join in.", "it": "Chi aspetta giovedì perde domenica. Unisciti e basta.", "fr": "Attends jusqu'à jeudi et tu rates dimanche. Rejoins, c'est tout.", "es": "Si esperas hasta el jueves, pierdes el domingo. Únete y ya."],

    "push.nearby_single_title": ["de": "{activity} läuft gerade", "en": "{activity} is on", "it": "{activity} in corso", "fr": "{activity} en cours", "es": "{activity} en marcha"],
    "push.nearby_single_body":  ["de": "{name} ist dabei — {dist} entfernt.", "en": "{name} is in — {dist} away.", "it": "{name} partecipa — a {dist}.", "fr": "{name} participe — à {dist}.", "es": "{name} está — a {dist}."],
