    "push.nearby_multi_body":   ["de": "{top} und mehr — jetzt auf der Karte.", "en": "{top} and more — on the map now.", "it": "{top} e altri — ora sulla mappa.", "fr": "{top} et plus — sur la carte maintenant.", "es": "{top} y más — ahora en el mapa."],

    "push.ph_start.1_title":    ["de": "Power-Hour startet",                    "en": "Power Hour starts"],
    "push.ph_start.1_body":     ["de": "Doppelter Boost-Bonus aktiv — +25 Punkte für jede Runde, den du jetzt erstellst oder triffst.", "en": "Double boost bonus active — +25 points for every round you create or meet now."],
    "push.ph_start.2_title":    ["de": "Bonus-Zeit läuft",                      "en": "Bonus time is on"],
    "push.ph_start.2_body":     ["de": "Wer jetzt eine Runde startet, bekommt +25 Punkte — sieh wer in der Nähe Lust auf was hat.", "en": "Start a Plan now for +25 points — see who's down nearby."],
    "push.ph_start.3_title":    ["de": "Dazu Power-Hour",                      "en": "Dazu Power Hour"],
    "push.ph_start.3_body":     ["de": "Mehr Punkte als sonst (+25 statt +15). Perfekter Moment für nen Spontan-Runde.", "en": "More points than usual (+25 instead of +15). Perfect time for a spontaneous Plan."],
    "push.ph_pre.1_title":      ["de": "Power-Hour in 1 Stunde",                "en": "Power Hour in 1 hour"],
    "push.ph_pre.1_body":       ["de": "Gleich gibt's +25 Punkte für jede Runde — bereite dich vor.", "en": "+25 points per Plan coming up — get ready."],
    "push.ph_pre.2_title":      ["de": "Bald Power-Hour",                          "en": "Power Hour soon"],
    "push.ph_pre.2_body":       ["de": "In einer Stunde startet der doppelte Boost-Bonus.", "en": "Double boost bonus starts in an hour."],
    "push.ph_pre.3_title":      ["de": "1 Stunde bis Power-Hour",               "en": "1 hour until Power Hour"],
    "push.ph_pre.3_body":       ["de": "Mach eine Runde — gleich gibt's +25 statt +15 Punkte.", "en": "Make a plan — +25 instead of +15 points are on the way."],
    "push.ph_end.1_title":      ["de": "Power-Hour endet in 1 Stunde",          "en": "Power Hour ends in 1 hour"],
    "push.ph_end.1_body":       ["de": "Letzte Chance auf +25 Punkte — wer jetzt noch eine Runde startet, kassiert den Bonus.", "en": "Last chance for +25 points — start a Plan now to grab the bonus."],
    "push.ph_end.2_title":      ["de": "Letzte Stunde Bonus",                      "en": "Last bonus hour"],
    "push.ph_end.2_body":       ["de": "Power-Hour läuft noch 60 Minuten. Jetzt einen Runde erstellen lohnt sich extra.", "en": "Power Hour runs 60 more minutes. Creating a Plan is extra worth it now."],
    "push.ph_end.3_title":      ["de": "Endspurt",                              "en": "Home stretch"],
    "push.ph_end.3_body":       ["de": "Eine Stunde übrig für den Power-Hour-Bonus.", "en": "One hour left for the Power Hour bonus."],

    "push.evening.1_title":     ["de": "Lust auf was heute Abend?", "en": "Up for something tonight?", "it": "Voglia di qualcosa stasera?", "fr": "Partant pour quelque chose ce soir ?", "es": "¿Te apetece algo esta noche?"],
    "push.evening.1_body":      ["de": "Starte eine Runde — wer in der Nähe Bock hat, kommt dazu.", "en": "Start a round — whoever's down nearby joins.", "it": "Avvia una sessione — chi ha voglia nelle vicinanze si unisce.", "fr": "Lance une session — ceux qui sont partants rejoignent.", "es": "Inicia una sesión — quien tenga ganas cerca se une."],
    "push.evening.2_title":     ["de": "Feierabend-Runde?", "en": "After-work plans?", "it": "Dopo lavoro?", "fr": "Après-boulot ?", "es": "¿Plan tras el trabajo?"],
    "push.evening.2_body":      ["de": "Bier, Park, Spaziergang — 30 Sekunden, dann ist deine Runde live.", "en": "Beer, park, walk — 30 seconds and your round is live.", "it": "Birra, parco, passeggiata — 30 secondi e la tua sessione è live.", "fr": "Bière, parc, balade — 30 secondes et ta session est en ligne.", "es": "Cerveza, parque, paseo — 30 segundos y tu sesión está en vivo."],
    "push.evening.3_title":     ["de": "Wer trifft sich gerade?", "en": "Who's meeting up right now?", "it": "Chi si incontra ora?", "fr": "Qui se retrouve maintenant ?", "es": "¿Quién queda ahora?"],
    "push.evening.3_body":      ["de": "Karte auf, schau wer was vorhat — oder starte selbst was.", "en": "Open the map, see who's up to something — or start something yourself.", "it": "Apri la mappa, vedi chi è attivo — o lancia qualcosa tu.", "fr": "Ouvre la carte, vois qui fait quoi — ou lance toi-même quelque chose.", "es": "Abre el mapa, mira quién hay — o lanza algo tú."],
    "push.evening.4_title":     ["de": "Spontan ist heute drin", "en": "Spontaneous is on tonight", "it": "Oggi è giornata spontanea", "fr": "Spontané c'est pour ce soir", "es": "Hoy toca espontaneidad"],
    "push.evening.4_body":      ["de": "Keine Runde? Mach einen. Andere sehen's sofort.", "en": "No plan? Make one. Everyone nearby sees it instantly.", "it": "Nessun piano? Fallo tu. Chi è vicino lo vede subito.", "fr": "Pas de plan ? Lance-en un. Les autres le voient tout de suite.", "es": "¿Sin plan? Haz uno. Los demás lo ven al instante."],
    "push.evening.5_title":     ["de": "Dein dazu-Reminder", "en": "Your dazu reminder", "it": "Il tuo promemoria dazu", "fr": "Ton rappel dazu", "es": "Tu recordatorio dazu"],
    "push.evening.5_body":      ["de": "Noch 5 Minuten und du bist draußen. Starte einfach was, der Rest kommt von allein.", "en": "5 more minutes and you're out the door. Start something, the rest follows.", "it": "Ancora 5 minuti e sei fuori. Lancia qualcosa, il resto viene da sé.", "fr": "Encore 5 minutes et tu sors. Lance quelque chose, le reste suit.", "es": "Cinco minutos y estás fuera. Lanza algo, el resto llega solo."],

    "push.homezone.1_title":    ["de": "Du bist in deiner Heimzone", "en": "You're in your home zone", "it": "Sei nella tua zona di casa", "fr": "Tu es dans ta zone d'habitation", "es": "Estás en tu zona de inicio"],
    "push.homezone.1_body_multi": ["de": "{count} Pläne sind gerade in deiner Nähe — andere könnten deinen Standort sehen.", "en": "{count} Plans are nearby — others might see your location.", "it": "{count} piani vicino a te — altri potrebbero vedere la tua posizione.", "fr": "{count} plans à proximité — d'autres pourraient voir ta position.", "es": "{count} planes cerca — otros podrían ver tu ubicación."],
    "push.homezone.1_body_single": ["de": "Eine Runde ist gerade in deiner Nähe — andere könnten deinen Standort sehen.", "en": "A Plan is nearby — others might see your location.", "it": "Una sessione è vicino a te — altri potrebbero vedere la tua posizione.", "fr": "Une session est à proximité — d'autres pourraient voir ta position.", "es": "Una sesión cerca — otros podrían ver tu ubicación."],
    "push.homezone.2_title":    ["de": "Heimzone betreten", "en": "Home zone entered", "it": "Zona di casa raggiunta", "fr": "Zone d'habitation atteinte", "es": "Zona de inicio alcanzada"],
    "push.homezone.2_body":     ["de": "Pläne in der Nähe können deinen ungefähren Wohnort sichtbar machen. Sei vorsichtig.", "en": "Nearby Plans can reveal your approximate home location. Be careful.", "it": "I piani vicini possono rivelare approssimativamente dove abiti. Fai attenzione.", "fr": "Les plans proches peuvent révéler ton lieu d'habitation approximatif. Fais attention.", "es": "Los planes cercanos pueden revelar tu ubicación aproximada. Ten cuidado."],
    "push.homezone.3_title":    ["de": "Privatsphäre-Hinweis", "en": "Privacy notice", "it": "Avviso privacy", "fr": "Avis de confidentialité", "es": "Aviso de privacidad"],
    "push.homezone.3_body":     ["de": "Du bist nahe deiner Heimzone und es gibt aktive Pläne. Möchtest du wirklich beitreten?", "en": "You're near your home zone and there are active Plans. Do you really want to join?", "it": "Sei vicino alla tua zona di casa e ci sono piani attivi. Vuoi davvero unirti?", "fr": "Tu es près de ta zone d'habitation et il y a des plans actifs. Veux-tu vraiment rejoindre ?", "es": "Estás cerca de tu zona de inicio y hay planes activos. ¿Seguro que quieres unirte?"],

    "push.join_req_title":      ["de": "{joiner} will mitmachen", "en": "{joiner} wants to join", "it": "{joiner} vuole partecipare", "fr": "{joiner} veut participer", "es": "{joiner} quiere unirse"],
    "push.join_req_body":       ["de": "Zu deiner {activity}-Runde — tippe zum Bestätigen.", "en": "To your {activity} round — tap to confirm.", "it": "Alla tua sessione {activity} — tocca per confermare.", "fr": "À ta session {activity} — appuie pour confirmer.", "es": "A tu sesión {activity} — toca para confirmar."],
    "push.auto_acc_title":      ["de": "{joiner} ist dabei", "en": "{joiner} is in", "it": "{joiner} partecipa", "fr": "{joiner} participe", "es": "{joiner} está dentro"],
    "push.auto_acc_body":       ["de": "Automatisch bestätigt — niemand hat reagiert.", "en": "Auto-confirmed — nobody responded.", "it": "Confermato in automatico — nessuno ha risposto.", "fr": "Auto-confirmé — personne n'a répondu.", "es": "Confirmado automático — nadie respondió."],
    "push.my_join_acc_title":   ["de": "Du bist dabei", "en": "You're in", "it": "Partecipi", "fr": "Tu participes", "es": "Estás dentro"],
