    "push.host_cancel_title":   ["de": "{host} hat die Runde beendet", "en": "{host} ended the round", "it": "{host} ha chiuso la sessione", "fr": "{host} a mis fin à la session", "es": "{host} terminó la sesión"],
    "push.host_cancel_body":    ["de": "Die {activity}-Runde ist zu Ende.", "en": "The {activity} round is over.", "it": "La sessione {activity} è finita.", "fr": "La session {activity} est terminée.", "es": "La sesión {activity} terminó."],
    "push.dropin_title":        ["de": "{joiner} ist dabei", "en": "{joiner} joined", "it": "{joiner} partecipa", "fr": "{joiner} participe", "es": "{joiner} se unió"],
