    "tab.bluetooth_explainer":          ["de": "Hingehen, Bluetooth bestätigt automatisch. Kein Check-in, kein Chat. Pläne ohne Planung.", "en": "Just go, Bluetooth confirms automatically. No check-in, no chat. Plans without the planning.", "it": "Vai, il Bluetooth conferma in automatico. Niente check-in, niente chat. Piani senza pianificare.", "fr": "Vas-y, le Bluetooth confirme tout seul. Pas de check-in, pas de chat. Plans sans planification.", "es": "Ve y ya, el Bluetooth confirma solo. Sin check-in, sin chat. Planes sin planear."],
    "tab.push_on_title":                ["de": "Push an, sonst verpasst du's", "en": "Turn Push on, or you'll miss out", "it": "Attiva le push o te lo perdi", "fr": "Active les push ou tu rates tout", "es": "Activa las notis o te lo pierdes"],
    "tab.push_on_body":                 ["de": "Dein erster Runde steht — stark.\n\nOhne Push merkst du nicht, wenn jemand zu dir kommt oder Freunde in der Nähe was starten.", "en": "Your first plan is up — nice.\n\nWithout push you won't notice when someone joins you or friends nearby start something.", "it": "La tua prima sessione è live — ottimo.\n\nSenza push non noti chi si unisce o cosa lanciano i tuoi amici vicini.", "fr": "Ta première session est lancée — top.\n\nSans push tu ne vois pas qui rejoint ou ce que tes amis lancent près de toi.", "es": "Tu primera sesión está en vivo — genial.\n\nSin push no verás quién se une o qué lanzan tus amigos cerca."],
    "tab.enable_push":                  ["de": "Push aktivieren", "en": "Enable Push", "it": "Attiva push", "fr": "Activer push", "es": "Activar push"],
    "tab.maybe_later":                  ["de": "Vielleicht später", "en": "Maybe later", "it": "Forse dopo", "fr": "Peut-être plus tard", "es": "Quizá después"],
    "tab.make_first_drop":              ["de": "Mach deinen erste Runde", "en": "Make your first Plan", "it": "Crea la tua prima sessione", "fr": "Lance ta première session", "es": "Crea tu primera sesión"],
    "tab.just_look_around":             ["de": "Erstmal nur schauen", "en": "Just look around", "it": "Prima guarda in giro", "fr": "D'abord jeter un œil", "es": "Primero mirar un poco"],
    "tab.no_access":                    ["de": "Ohne Zugriff geht nichts", "en": "Nothing works without access", "it": "Senza accesso non funziona", "fr": "Rien ne marche sans accès", "es": "Nada funciona sin acceso"],
    "tab.no_access_body":               ["de": "Dazu braucht Standort oder Bluetooth — sonst kann's dich nicht erkennen wenn du da bist. Eines reicht, beide sind besser.", "en": "Dazu needs location or Bluetooth — otherwise it can't detect you when you're there. One is enough, both is better.", "it": "dazu ha bisogno di posizione o Bluetooth — altrimenti non ti riconosce quando sei lì. Una basta, due è meglio.", "fr": "dazu a besoin de la position ou du Bluetooth — sinon il ne peut pas te détecter quand tu es là. Un suffit, les deux c'est mieux.", "es": "dazu necesita ubicación o Bluetooth — si no, no puede detectarte cuando estés allí. Uno basta, los dos es mejor."],
    "tab.open_settings":                ["de": "Einstellungen öffnen", "en": "Open Settings", "it": "Apri impostazioni", "fr": "Ouvrir les paramètres", "es": "Abrir ajustes"],
