// MARK: - tr() Helper

/// Gibt den lokalisierten String für den aktuellen `appLanguage`-Wert zurück.
/// Liest direkt aus UserDefaults — wird automatisch aktualisiert wenn eine
/// View `@AppStorage("appLanguage")` als DynamicProperty enthält.
/// Fallback-Kette: gewählte Sprache → Deutsch → Key selbst (für Debugging).
func tr(_ key: String) -> String {
    let lang = UserDefaults.standard.string(forKey: "appLanguage") ?? "de"
    let entry = strings[key]
    // Reihenfolge: aktive Sprache → Englisch (int. Fallback) → Deutsch
    // (Quell-Sprache) → Key als letzte Rettung. Vorher nur direkter DE-
    // Fallback; dadurch sahen IT/FR/ES-User für die vielen noch nicht
    // übersetzten Strings deutsche Texte.
    return entry?[lang] ?? entry?["en"] ?? entry?["de"] ?? key
}

/// Übersetzt raw scheduledTime-Werte (intern als deutsche Strings in Firebase gespeichert)
/// in die aktuelle App-Sprache für die Anzeige.
func trScheduledTime(_ raw: String) -> String {
    switch raw {
    case "Jetzt":       return tr("create.now")
    default:            return raw
    }
}
